import{_ as i,l as o,o as r,b as S,d as n,f as s,m as e,q as d}from"./chunks/framework.Tf23FRXt.js";const x=JSON.parse('{"title":"伊甸希望乐园 觉醒之章4","description":"","frontmatter":{},"headers":[],"relativePath":"duty/689.htm.md","filePath":"duty/689.md","lastUpdated":1791098838000}'),p={name:"duty/689.htm.md"};function a(m,t,u,O,B,f){const l=o("Status");return r(),S("div",null,[t[7]||(t[7]=n("h1",{id:"伊甸希望乐园-觉醒之章4",tabindex:"-1"},"伊甸希望乐园 觉醒之章 4",-1)),t[8]||(t[8]=n("p",null,"场地是 4x4 的方格，技能基本上都以这些方格为单位进行结算。",-1)),n("p",null,[t[0]||(t[0]=n("mark",null,"崩岩",-1)),t[1]||(t[1]=s("是对当前 MT 大伤害，附带",-1)),e(l,{id:493,name:"物理受伤加重"}),t[2]||(t[2]=s("效果，不过其实基本是奶的起来的，所以建议进本后双 T 交流是否换 T。",-1))]),t[9]||(t[9]=d("<p><mark>邪土</mark>是扩散型 AOE，先一块地板亮起，然后它周围的 8 块地板亮起，然后是再外围的地板亮起，需要玩家在外围等待，里面的地板炸了之后立刻向里移动。</p><p>BOSS 喊话<ins>覆于我身的坚硬地壳啊！<ins>的第二行，若是</ins>化为手甲碾碎敌人！</ins>，则 BOSS 背上的齿轮甲会跑到 BOSS 手上，玩家需要先在 BOSS 正面一排岩石躲避 AOE，然后脚下会变蓝，向两侧躲避即可；若第二行是<ins>化为车轮驰骋大地！</ins>，BOSS 会变为摩托车形态，需要在 BOSS 两侧相对较宽的一侧躲避（然后被击退，同时出现需要躲避的蓝色地板）。</p><p>落石有几种模式：</p><ul><li>两块石头带衰减 AOE 提示：先在场边躲避衰减型 AOE，落下的两块岩石会有一块爆炸（发黄），玩家需要在另一块岩石背后躲避 BOSS 接下来的全屏 AOE。</li><li>四角雷：落下 4 块岩石，其中一块会与 BOSS 连线变大，在没有大石头的两侧贴边躲避（比如左下角的石头变大了，则在右边或上边的中间点躲避）。</li><li>三排雷：会在 4x4 方格的交点处依次落下 3 排雷，BOSS 会跟其中一个雷连线使之变大，玩家需要避开大雷的同时，前往第三排雷的位置，等第一排雷炸了之后，向第一排雷移动。每个小雷的爆炸范围是 2x2 方砖的内接正圆就，因此可以躲避的位置还是比较多的，如果实在不会躲可以跟着人群走。</li><li>米字雷：会先落下十字型的雷，再落下四角雷，需要先在四角躲避，十字雷炸了之后去中间躲四角炸。</li></ul><p>由于两块落岩和米字雷有可能与邪土同时出现，二雷的时候先处理邪土；米字雷四角躲避后观察邪土方向躲避（冷静应对）。</p>",5)),n("p",null,[t[3]||(t[3]=s("BOSS 读条",-1)),t[4]||(t[4]=n("mark",null,"大地之怒",-1)),t[5]||(t[5]=s("会给全团上",-1)),e(l,{id:1474,name:"污泥"}),t[6]||(t[6]=s("debuff，需要治疗注意抬血。",-1))])])}const A=i(p,[["render",a]]);export{x as __pageData,A as default};
